{"path": "packages/rails/src/rails.ts", "start_line": 1, "end_line": 207, "total_lines": 207, "content": "     1	import {
     2	  RailError,
     3	  makeSettlementRef,
     4	  type Clock,
     5	  type PaymentRail,
     6	  type PaymentRequest,
     7	  type Quote,
     8	  type RailAuthorization,
     9	  type RailSettlement,
    10	  type Micros,
    11	} from '@mwb/core';
    12	
    13	/**
    14	 * A rail is a backend: quote → authorize → settle, all behind one
    15	 * interface. Field names inside `payload` are intentionally opaque — the
    16	 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
    17	 * finalized), so the broker never parses them. Draft-caveat discipline:
    18	 * build against the interface, not a draft's field names.
    19	 */
    20	export interface RailBackend extends PaymentRail {}
    21	
    22	/**
    23	 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
    24	 * (micro-unit price, `X-PAYMENT` header) without an external service.
    25	 * Deterministic: with a `frozenClock` and fixed input, the settlement
    26	 * reference is stable so reconciliation can be asserted.
    27	 */
    28	export class InMemoryRail implements PaymentRail {
    29	  readonly id: string;
    30	  readonly priceMicros: Micros;
    31	  readonly currency: string;
    32	  readonly clock: Clock;
    33	  private readonly settlementSeed: string = '';
    34	  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';
    35	
    36	  constructor(options: {
    37	    id: string;
    38	    priceMicros: Micros;
    39	    currency?: string;
    40	    clock?: Clock;
    41	    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    42	    /** Stable suffix seed so settlement refs are deterministic in tests. */
    43	    settlementSeed?: string;
    44	  }) {
    45	    this.id = options.id;
    46	    this.priceMicros = options.priceMicros;
    47	    this.currency = options.currency ?? 'USD';
    48	    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    49	    this.failureMode = options.failureMode ?? 'none';
    50	    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
    51	  }
    52	
    53	  quote(_req: PaymentRequest): Promise<Quote> {
    54	    if (this.failureMode === 'quote') {
    55	      return Promise.reject(
    56	        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
    57	      );
    58	    }
    59	    const nowMs = Date.parse(this.clock.now());
    60	    return Promise.resolve({
    61	      unitsMicros: this.priceMicros,
    62	      currency: this.currency,
    63	      rail: this.id,
    64	      settlement: 'immediate',
    65	      expiresAt: new Date(nowMs + 60_000).toISOString(),
    66	    });
    67	  }
    68	
    69	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    70	    if (this.failureMode === 'authorize') {
    71	      return Promise.reject(
    72	        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
    73	      );
    74	    }
    75	    const payload = JSON.stringify({
    76	      schema: 'urn:rail:' + this.id,
    77	      amountMicros: quote.unitsMicros,
    78	      currency: quote.currency,
    79	      url: String(req.url),
    80	      method: req.method,
    81	    });
    82	    return Promise.resolve({
    83	      scheme: this.id,
    84	      payload,
    85	      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    86	    });
    87	  }
    88	
    89	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    90	    if (this.failureMode === 'settle') {
    91	      return Promise.reject(
    92	        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
    93	      );
    94	    }
    95	    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    96	    return Promise.resolve({
    97	      rail: this.id,
    98	      // Deterministic from (seed, url) so tests can assert reconciliation.
    99	      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
   100	      amountMicros: parsed.amountMicros,
   101	      currency: parsed.currency,
   102	      settledAt: this.clock.now(),
   103	    });
   104	  }
   105	}
   106	
   107	/**
   108	 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
   109	 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
   110	 * only this minimal shape — it does not depend on the bridge's own types.
   111	 * That is the "one contract" boundary in practice.
   112	 */
   113	export interface BridgeClientShape {
   114	  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
   115	  authorize(input: {
   116	    url: string;
   117	    method: string;
   118	    headers: Record<string, string>;
   119	    quote: { unitsMicros: number; currency: string };
   120	  }): Promise<RailAuthorization>;
   121	  settle(input: {
   122	    url: string;
   123	    method: string;
   124	    headers: Record<string, string>;
   125	    authorization: RailAuthorization;
   126	  }): Promise<RailSettlement>;
   127	}
   128	
   129	export class BridgeRail implements PaymentRail {
   130	  constructor(
   131	    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
   132	  ) {}
   133	
   134	  get id(): string {
   135	    return this.idAndBridge.id;
   136	  }
   137	
   138	  quote(req: PaymentRequest): Promise<Quote> {
   139	    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
   140	  }
   141	
   142	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   143	    return this.idAndBridge.bridge.authorize({
   144	      url: String(req.url),
   145	      method: req.method,
   146	      headers: req.headers,
   147	      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
   148	    });
   149	  }
   150	
   151	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   152	    return this.idAndBridge.bridge.settle({
   153	      url: String(req.url),
   154	      method: req.method,
   155	      headers: req.headers,
   156	      authorization,
   157	    });
   158	  }
   159	}
   160	
   161	/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
   162	export class RailRegistry {
   163	  private readonly rails = new Map<string, PaymentRail>();
   164	
   165	  register(rail: PaymentRail): this {
   166	    if (this.rails.has(rail.id)) {
   167	      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
   168	    }
   169	    this.rails.set(rail.id, rail);
   170	    return this;
   171	  }
   172	
   173	  deregister(id: string): boolean {
   174	    return this.rails.delete(id);
   175	  }
   176	
   177	  get(id: string): PaymentRail {
   178	    const r = this.rails.get(id);
   179	    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
   180	    return r;
   181	  }
   182	
   183	  /** Look up a rail by id without throwing when it is absent. */
   184	  optional(id: string): PaymentRail | undefined {
   185	    return this.rails.get(id);
   186	  }
   187	
   188	  ids(): string[] {
   189	    return [...this.rails.keys()].sort();
   190	  }
   191	}
   192	
   193	/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
   194	function deterministicRand(seed: string): () => number {
   195	  let h = 2166136261;
   196	  for (let i = 0; i < seed.length; i++) {
   197	    h ^= seed.charCodeAt(i);
   198	    h = Math.imul(h, 16777619);
   199	  }
   200	  return () => {
   201	    h += 0x6d2b79f5;
   202	    let t = h;
   203	    t = Math.imul(t ^ (t >>> 15), t | 1);
   204	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
   205	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   206	  };
   207	}"}

{"path": "packages/rails/src/selfsettle.ts", "start_line": 1, "end_line": 667, "total_lines": 667, "content": "     1	/**
     2	 * Self-hosted 402 settlement backend.
     3	 *
     4	 * The metered path (see `packages/gateway/src/broker.ts`) is:
     5	 *
     6	 *   rail.quote -> rail.authorize -> rail.settle -> origin.fetch(...)
     7	 *
     8	 * The rail's `settle` step is the payment commit. Previously `SelfHosted402Rail`
     9	 * only extended the in-memory stub, so a "self 402" never actually minted a
    10	 * proof, rejected a reused proof, or recorded a final receipt. This module
    11	 * makes it real:
    12	 *
    13	 *   1. The broker signs an Ed25519 **payment mandate** (a spend authorization)
    14	 *      over an opaque manifest, carrying a per-request nonce.
    15	 *   2. The rail POSTs that signed mandate to a settlement backend. The backend
    16	 *      verifies the signature, rejects a **replayed** nonce, signs a chained
    17	 *      settlement **receipt**, and returns it. A replayed proof throws
    18	 *      `RAIL_REPLAY` (non-retryable) — the broker maps a settle fault to
    19	 *      `payment-required`, exactly as an origin that still demanded payment.
    20	 *   3. The receipt lands in a small, Ed25519-**chained, tamper-evident ledger**
    21	 *      that the audit/`reconcile` surface can read.
    22	 *
    23	 * The wire form is intentionally minimal (draft-caveat: build against the
    24	 * *pattern* of x402's `PAYMENT-SIGNATURE`/`X-PAYMENT`, not its field names).
    25	 * The same backend runs in-process (tests, dev) or behind a thin HTTP service
    26	 * (`SettlementHttpServer`) on a separate host (`HttpSettlementClient`), so the
    27	 * rail needs no compile-time knowledge of where the backend lives.
    28	 *
    29	 * Crypto mirrors `packages/identity/src/ring.ts`: Ed25519 over a JWK, and the
    30	 * broker's own `b64url`/`fromB64url` from `@mwb/core`. No new dependency.
    31	 */
    32	
    33	import {
    34	  generateKeyPairSync,
    35	  sign,
    36	  verify,
    37	  createPrivateKey,
    38	  createPublicKey,
    39	  randomBytes,
    40	} from 'node:crypto';
    41	import {
    42	  RailError,
    43	  systemClock,
    44	  b64url,
    45	  fromB64url,
    46	  type Clock,
    47	  type PaymentRail,
    48	  type PaymentRequest,
    49	  type Quote,
    50	  type RailAuthorization,
    51	  type RailSettlement,
    52	  type Micros,
    53	} from '@mwb/core';
    54	
    55	/** The opaque mandate type the broker mints. Not a draft's field set. */
    56	const PAYMENT_MANDATE_TYPE = 'urn:mwb:self402:payment-mandate:v1';
    57	
    58	/** Fixed key order so the manifest bytes are byte-identical at sign and verify. */
    59	const MANDATE_FIELDS = [
    60	  'origin',
    61	  'url',
    62	  'amountMicros',
    63	  'currency',
    64	  'nonce',
    65	  'issuedAt',
    66	  'recipient',
    67	] as const;
    68	
    69	/** Accept a mandate whose `issuedAt` is within this window of the clock. */
    70	const ACCEPTANCE_WINDOW_MS = 5 * 60 * 1000;
    71	
    72	/** The header the rail injects on the settled origin request (holds the proof). */
    73	export const PAYMENT_HEADER = 'x-payment';
    74	
    75	/** An Ed25519 spend-authorizer. `privateKey` never leaves the signing side. */
    76	export interface SettlementKey {
    77	  keyId: string;
    78	  algorithm: 'ed25519';
    79	  /** 32-byte public key, JWK `x`, base64url. Shares the verifier. */
    80	  publicKey: string;
    81	  /** 32-byte seed, JWK `d`, base64url. Never leaves the broker. */
    82	  privateKey: string;
    83	  createdAt: string;
    84	}
    85	
    86	/** Mint a settlement key (broker's spend authorizer). */
    87	export function makeSettlementKey(
    88	  clock: Clock = systemClock,
    89	  keyId = `settle_${clock.now().replace(/[^A-Za-z0-9]/g, '')}`,
    90	): SettlementKey {
    91	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
    92	  const pub = publicKey.export({ format: 'jwk' }) as { x?: string };
    93	  const priv = privateKey.export({ format: 'jwk' }) as { d?: string };
    94	  if (!pub.x || !priv.d) {
    95	    throw new RailError('failed to export Ed25519 JWK', 'SETTLEMENT_KEY');
    96	  }
    97	  return {
    98	    keyId,
    99	    algorithm: 'ed25519',
   100	    publicKey: b64url(fromB64url(pub.x)),
   101	    privateKey: b64url(fromB64url(priv.d)),
   102	    createdAt: clock.now(),
   103	  };
   104	}
   105	
   106	function privateKeyObject(k: SettlementKey): ReturnType<typeof createPrivateKey> {
   107	  return createPrivateKey({
   108	    format: 'jwk',
   109	    key: { kty: 'OKP', crv: 'Ed25519', d: k.privateKey, x: k.publicKey },
   110	  });
   111	}
   112	
   113	function publicKeyObject(k: SettlementKey): ReturnType<typeof createPublicKey> {
   114	  return createPublicKey({
   115	    format: 'jwk',
   116	    key: { kty: 'OKP', crv: 'Ed25519', x: k.publicKey },
   117	  });
   118	}
   119	
   120	function signBytes(k: SettlementKey, buf: Buffer): string {
   121	  return b64url(new Uint8Array(sign(null, buf, privateKeyObject(k))));
   122	}
   123	
   124	function verifyBytes(k: SettlementKey, buf: Buffer, sigB64: string): boolean {
   125	  try {
   126	    return verify(null, buf, publicKeyObject(k), Buffer.from(fromB64url(sigB64)));
   127	  } catch {
   128	    return false;
   129	  }
   130	}
   131	
   132	/** The signed spend authorization the broker mints and the rail commits. */
   133	export interface PaymentMandateManifest {
   134	  origin: string;
   135	  url: string;
   136	  amountMicros: number;
   137	  currency: string;
   138	  nonce: string;
   139	  issuedAt: string;
   140	  recipient: string;
   141	}
   142	
   143	export interface PaymentMandate extends PaymentMandateManifest {
   144	  signature: string;
   145	}
   146	
   147	function manifestBytes(m: PaymentMandateManifest): Buffer {
   148	  const obj: Record<string, number | string> = {};
   149	  for (const f of MANDATE_FIELDS) obj[f] = m[f];
   150	  return Buffer.from(JSON.stringify(obj), 'utf8');
   151	}
   152	
   153	/** Build (sign) a payment mandate. */
   154	export function buildMandate(o: {
   155	  origin: string;
   156	  url: string;
   157	  amountMicros: number;
   158	  currency: string;
   159	  recipient: string;
   160	  clock: Clock;
   161	  key: SettlementKey;
   162	  nonce?: string;
   163	  issuedAt?: string;
   164	}): PaymentMandate {
   165	  const nonce = o.nonce ?? randomBytes(32).toString('base64url');
   166	  const issuedAt = o.issuedAt ?? o.clock.now();
   167	  const manifest: PaymentMandateManifest = {
   168	    origin: o.origin,
   169	    url: o.url,
   170	    amountMicros: o.amountMicros,
   171	    currency: o.currency,
   172	    nonce,
   173	    issuedAt,
   174	    recipient: o.recipient,
   175	  };
   176	  return { ...manifest, signature: signBytes(o.key, manifestBytes(manifest)) };
   177	}
   178	
   179	export interface VerifyResult {
   180	  valid: boolean;
   181	  reason?: string;
   182	}
   183	
   184	/**
   185	 * Verify a mandate's signature, manifest, and acceptance window. Does not
   186	 * consume the nonce — the origin can call this to gate content release.
   187	 */
   188	export function verifyMandate(
   189	  m: PaymentMandate,
   190	  key: SettlementKey,
   191	  opts?: { nowMs?: number },
   192	): VerifyResult {
   193	  if (typeof m.signature !== 'string' || m.signature.length === 0) {
   194	    return { valid: false, reason: 'missing-signature' };
   195	  }
   196	  if (!verifyBytes(key, manifestBytes(m), m.signature)) {
   197	    return { valid: false, reason: 'signature-mismatch' };
   198	  }
   199	  const iat = Date.parse(m.issuedAt);
   200	  if (Number.isNaN(iat)) return { valid: false, reason: 'bad-issuedAt' };
   201	  const nowMs = opts?.nowMs ?? Date.now();
   202	  if (Math.abs(nowMs - iat) > ACCEPTANCE_WINDOW_MS) {
   203	    return { valid: false, reason: 'issued-out-of-window' };
   204	  }
   205	  if (!(m.amountMicros > 0)) return { valid: false, reason: 'non-positive-amount' };
   206	  return { valid: true };
   207	}
   208	
   209	/** A receipt minted by the backend, signed by its key. */
   210	export interface SettlementReceipt {
   211	  settlementRef: string;
   212	  origin: string;
   213	  url: string;
   214	  amountMicros: number;
   215	  currency: string;
   216	  nonce: string;
   217	  issuedAt: string;
   218	  settledAt: string;
   219	}
   220	
   221	/** One entry in the chained, tamper-evident settlement ledger. */
   222	export interface LedgerRecord {
   223	  seq: number;
   224	  receipt: SettlementReceipt;
   225	  signedAt: string;
   226	  /** Signature over `${seq}\0${ref}\0${previousSignature}`. */
   227	  signature: string;
   228	}
   229	
   230	/**
   231	 * The settlement backend: verifies signed mandates, enforces replay
   232	 * protection (a nonce is consumed exactly once), and records a final,
   233	 * cryptographically-chained receipt ledger. Runs in-process.
   234	 */
   235	export class SettlementServer {
   236	  readonly key: SettlementKey;
   237	  readonly clock: Clock;
   238	  private readonly consumed = new Set<string>();
   239	  private readonly ledgerRows: LedgerRecord[] = [];
   240	
   241	  constructor(options: { key: SettlementKey; clock?: Clock }) {
   242	    this.key = options.key;
   243	    this.clock = options.clock ?? systemClock;
   244	  }
   245	
   246	  /** Pure: is this mandate's signature valid and in-window? (No state change.) */
   247	  isValidMandate(m: PaymentMandate): boolean {
   248	    return verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) }).valid;
   249	  }
   250	
   251	  /** Verify and, on first use, consume the nonce, then mint a receipt. */
   252	  verify(m: PaymentMandate): VerifyResult {
   253	    const v = verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) });
   254	    if (!v.valid) return v;
   255	    if (this.consumed.has(m.nonce)) {
   256	      return { valid: false, reason: 'replayed-proof' };
   257	    }
   258	    return { valid: true };
   259	  }
   260	
   261	  /**
   262	   * The payment commit. Verifies, rejects a replayed nonce (throwing
   263	   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   264	   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   265	   */
   266	  settle(m: PaymentMandate): RailSettlement {
   267	    const v = this.verify(m);
   268	    if (!v.valid) {
   269	      throw new RailError(
   270	        `settlement rejected: ${v.reason ?? 'unknown'}`,
   271	        'RAIL_SETTLE',
   272	        undefined,
   273	        false,
   274	      );
   275	    }
   276	    const settledAt = this.clock.now();
   277	    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
   278	    const receipt: SettlementReceipt = {
   279	      settlementRef,
   280	      origin: m.origin,
   281	      url: m.url,
   282	      amountMicros: m.amountMicros,
   283	      currency: m.currency,
   284	      nonce: m.nonce,
   285	      issuedAt: m.issuedAt,
   286	      settledAt,
   287	    };
   288	    const prevSig = this.ledgerRows.length > 0 ? this.ledgerRows[this.ledgerRows.length - 1]!.signature : 'genesis';
   289	    const seq = this.ledgerRows.length + 1;
   290	    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
   291	    const signature = signBytes(this.key, chain);
   292	    this.ledgerRows.push({ seq, receipt, signedAt: settledAt, signature });
   293	    this.consumed.add(m.nonce);
   294	    return {
   295	      rail: 'self402',
   296	      settlementRef,
   297	      amountMicros: m.amountMicros,
   298	      currency: m.currency,
   299	      settledAt,
   300	    };
   301	  }
   302	
   303	  /** The current settlement ledger (a copy) — surfaced on the audit view. */
   304	  ledger(): LedgerRecord[] {
   305	    return this.ledgerRows.map((r) => ({ ...r, receipt: { ...r.receipt } }));
   306	  }
   307	
   308	  /** How many distinct nonces have been settled (== ledger length). */
   309	  settledCount(): number {
   310	    return this.ledgerRows.length;
   311	  }
   312	}
   313	
   314	/**
   315	 * A `PaymentRail` backed by a settlement backend (in-process
   316	 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
   317	 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
   318	 * — the broker only sees `quote/authorize/settle`.
   319	 */
   320	export class SelfHosted402Rail implements PaymentRail {
   321	  readonly id = 'self402';
   322	
   323	  constructor(
   324	    private readonly backend: SettlementBackend,
   325	    private readonly key: SettlementKey,
   326	    private readonly opts: {
   327	      priceMicros: Micros;
   328	      currency?: string;
   329	      clock?: Clock;
   330	      origin?: string;
   331	    },
   332	  ) {}
   333	
   334	  async quote(_req: PaymentRequest): Promise<Quote> {
   335	    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
   336	    return {
   337	      unitsMicros: this.opts.priceMicros,
   338	      currency: this.opts.currency ?? 'USD',
   339	      rail: this.id,
   340	      settlement: 'immediate',
   341	      expiresAt: new Date(nowMs + 60_000).toISOString(),
   342	    };
   343	  }
   344	
   345	  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   346	    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
   347	    const mandate = buildMandate({
   348	      origin,
   349	      url: String(req.url),
   350	      amountMicros: quote.unitsMicros,
   351	      currency: this.opts.currency ?? 'USD',
   352	      recipient: this.key.keyId,
   353	      clock: this.opts.clock ?? systemClock,
   354	      key: this.key,
   355	    });
   356	    const xPayment = b64url(Buffer.from(JSON.stringify(mandate), 'utf8'));
   357	    return {
   358	      scheme: this.id,
   359	      payload: JSON.stringify(mandate),
   360	      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
   361	    };
   362	  }
   363	
   364	  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   365	    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
